package de.powerradio.studio; import android.app.*;import android.os.*;import android.content.*;import android.widget.*; public class MainActivity extends Activity {public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,60,24,24);TextView t=new TextView(this);t.setText("POWER RADIO Studio • Widget auf dem Startbildschirm hinzufügen");l.addView(t);for(int i=0;i<2;i++){final int n=i;Button x=new Button(this);x.setText(StudioWidget.stations[i]+" • PLAY / STOP");x.setOnClickListener(v->startForegroundService(new Intent(this,RadioService.class).putExtra("station",n)));l.addView(x);}setContentView(l);}}